void OG_ImplDX11_InvalidateDeviceObjects(){for(std::map<unsigned int,ID3D11ShaderResourceView*>::iterator it=g_Textures.begin();it!=g_Textures.end();++it)it->second->Release();g_Textures.clear();if(g_FontView){g_FontView->Release();g_FontView=0;}if(g_FontTexture){g_FontTexture->Release();g_FontTexture=0;}if(g_VB){g_VB->Release();g_VB=0;}if(g_IB){g_IB->Release();g_IB=0;}if(g_VS){g_VS->Release();g_VS=0;}if(g_PS){g_PS->Release();g_PS=0;}if(g_Layout){g_Layout->Release();g_Layout=0;}if(g_ConstantBuffer){g_ConstantBuffer->Release();g_ConstantBuffer=0;}if(g_Sampler){g_Sampler->Release();g_Sampler=0;}if(g_Blend){g_Blend->Release();g_Blend=0;}if(g_Raster){g_Raster->Release();g_Raster=0;}if(g_Depth){g_Depth->Release();g_Depth=0;}if(og::GetFontAtlas().tex_id)og::GetFontAtlas().tex_id=0;}
void OG_ImplDX11_Shutdown(){OG_ImplDX11_InvalidateDeviceObjects();if(g_Context){g_Context->Release();g_Context=0;}if(g_Device){g_Device->Release();g_Device=0;}}
void OG_ImplDX11_NewFrame(){if(!g_VS)OG_ImplDX11_CreateDeviceObjects();else if(!og::GetFontAtlas().tex_id){OG_ImplDX11_InvalidateDeviceObjects();OG_ImplDX11_CreateDeviceObjects();}}
