    D3D11_MAPPED_SUBRESOURCE mapped={};if(SUCCEEDED(g_Context->Map(g_ConstantBuffer,0,D3D11_MAP_WRITE_DISCARD,0,&mapped))){float L=data->display_pos.x,R=L+data->display_size.x,T=data->display_pos.y,B=T+data->display_size.y;float m[4][4]={{2/(R-L),0,0,0},{0,2/(T-B),0,0},{0,0,0.5f,0},{(R+L)/(L-R),(T+B)/(B-T),0.5f,1}};memcpy(mapped.pData,m,sizeof(m));g_Context->Unmap(g_ConstantBuffer,0);}
