    int global_v=0,global_i=0;for(size_t n=0;n<data->lists.size();++n){og::DrawList* dl=data->lists[n];for(size_t c=0;c<dl->cmds.size();++c){const og::DrawCmd& cmd=dl->cmds[c];if(!cmd.elem_count)continue;D3D11_RECT r={(LONG)cmd.clip_rect.x,(LONG)cmd.clip_rect.y,(LONG)cmd.clip_rect.z,(LONG)cmd.clip_rect.w};g_Context->RSSetScissorRects(1,&r);ID3D11ShaderResourceView* texture=FindTexture(cmd.tex_id);g_Context->PSSetShaderResources(0,1,&texture);g_Context->DrawIndexed(cmd.elem_count,cmd.idx_offset+global_i,global_v);}global_i+=(int)dl->idx.size();global_v+=(int)dl->vtx.size();}
